#!/usr/bin/env python3
"""
Inject 200 more Easter angles (10 categories × 20) and
200 more Christmas angles (10 categories × 20) into the
existing lifetogether-fresh-sermon-angles-v2.jsx file.

Easter structure:
  - 5 categories COMING INTO Easter (Lent/Holy Week approach)
  - 5 categories COMING OUT OF Easter (post-resurrection formation)

Christmas structure:
  - 5 categories COMING INTO Christmas (Advent approach)
  - 5 categories COMING OUT OF Christmas (Epiphany/formation)
"""

import re, html

def q(s):
    """Escape for JS string — just handle backslash and double-quote."""
    return s.replace('\\', '\\\\').replace('"', '\\"')

def angle(type_, title, sub, hook):
    return f'      {{type:"{q(type_)}",title:"{q(title)}",sub:"{q(sub)}",hook:"{q(hook)}"}},'

